23	{
24	    token_start = pos;
25	    token_length = 0;
26	    size_t code_points = 0;
27	    for (; code_points < n && token_start + token_length < length; ++code_points)
28	    {
29	        size_t sz = UTF8::seqLength(static_cast<UInt8>(data[token_start + token_length]));
30	        token_length += sz;
31	    }
32	    /// The sequence length is determined by the first character, but we should always check it does not go beyond the buffer length.
33	    token_length = std::min(token_length, length - token_start);
34	    pos += UTF8::seqLength(static_cast<UInt8>(data[pos]));
35	    return code_points == n;
36	}
